def _response(status=200, body=None, headers=None):
    resp = MagicMock()
    resp.ok = status < 400
    resp.status_code = status
    resp.headers = headers or {}
    content = json.dumps(body).encode() if body is not None else b""
    resp.content = content
    resp.json.side_effect = lambda: json.loads(content)
    return resp


class TestClientRequest(unittest.TestCase):
    def setUp(self):
        self.client = Client("test-key")

    def test_default_timeout_applied(self):
        with patch.object(self.client.session, "request") as mock_req:
            mock_req.return_value = _response(body={"data": []})
            self.client.list_objects()
            self.assertEqual(
                mock_req.call_args.kwargs["timeout"], Client.DEFAULT_TIMEOUT
            )

    def test_empty_body_returns_empty_dict(self):
        with patch.object(self.client.session, "request") as mock_req:
            mock_req.return_value = _response(body=None)
            self.assertEqual(self.client.delete_note("abc"), {})

    def test_retry_after_header_honored(self):
        rate_limited = _response(status=429, body={}, headers={"Retry-After": "0"})
        ok = _response(body={"data": []})
        with (
            patch.object(
                self.client.session, "request", side_effect=[rate_limited, ok]
            ),
            patch("py_attio.client.time.sleep") as mock_sleep,
        ):
            self.client.list_objects()
            mock_sleep.assert_called_once()

    def test_create_post_not_retried_on_network_error(self):
        with (
            patch.object(
                self.client.session,
                "request",
                side_effect=requests.exceptions.ConnectionError("boom"),
            ) as mock_req,
            patch("py_attio.client.time.sleep"),
        ):
            with self.assertRaises(requests.exceptions.ConnectionError):
                self.client.create_record("people", {"data": {}})
            self.assertEqual(mock_req.call_count, 1)

    def test_query_post_retried_on_network_error(self):
        ok = _response(body={"data": []})
        with (
            patch.object(
                self.client.session,
                "request",
                side_effect=[requests.exceptions.ConnectionError("boom"), ok],
            ) as mock_req,
            patch("py_attio.client.time.sleep"),
        ):
            self.client.list_records("people")
            self.assertEqual(mock_req.call_count, 2)


class TestPagination(unittest.TestCase):
    def setUp(self):
        self.client = Client("test-key")

    def test_payload_limit_overrides_page_size_stride(self):
        pages = [
            {"data": [{"id": str(i)} for i in range(10)]},
            {"data": [{"id": str(i)} for i in range(10, 15)]},
        ]
        offsets = []

        def fake_list_records(object_id, payload):
            offsets.append(payload["offset"])
            return pages[len(offsets) - 1]

        with patch.object(self.client, "list_records", side_effect=fake_list_records):
            records = list(
                self.client.paginate_records(
                    "companies", payload={"limit": 10}, page_size=100
                )
            )
        self.assertEqual(len(records), 15)
        self.assertEqual(offsets, [0, 10])


class TestUtils(unittest.TestCase):
    def test_extract_linked_record_ids_shapes(self):
        items = [
            {"target_record_id": "a"},
            {"record_id": "b"},
            {"id": {"record_id": "c"}},
            {"target": {"record_id": "d"}},
            "junk",
            {},
        ]
        self.assertEqual(extract_linked_record_ids(items), ["a", "b", "c", "d"])

    def test_extract_record_id(self):
        self.assertEqual(extract_record_id({"id": {"record_id": "x"}}), "x")
        self.assertEqual(extract_record_id({"id": "y"}), "y")
        self.assertIsNone(extract_record_id({}))

    def test_build_relationship_value_dedupes(self):
        value = build_relationship_value(["a", "b", "a", ""], "locations")
        self.assertEqual(
            value,
            [
                {"target_object": "locations", "target_record_id": "a"},
                {"target_object": "locations", "target_record_id": "b"},
            ],
        )

    def test_build_location_value_all_keys_present(self):
        value = build_location_value(
            line_1="1 Infinite Loop",
            locality="Cupertino",
            region="CA",
            postcode="95014",
            country_code="US",
        )
        self.assertEqual(
            set(value),
            {
                "line_1",
                "line_2",
                "line_3",
                "line_4",
                "locality",
                "region",
                "postcode",
                "country_code",
                "latitude",
                "longitude",
            },
        )
        self.assertEqual(value["locality"], "Cupertino")
        # blank/whitespace components normalize to None; unset stay None
        self.assertIsNone(value["line_2"])
        self.assertIsNone(build_location_value(line_1="  ")["line_1"])

    def test_build_record_payload_drops_none(self):
        payload = build_record_payload({"a": 1, "b": None, "hq": False})
        # None dropped; falsy-but-valid values (False, 0) kept
        self.assertEqual(payload, {"data": {"values": {"a": 1, "hq": False}}})
        kept = build_record_payload({"b": None}, drop_none=False)
        self.assertEqual(kept, {"data": {"values": {"b": None}}})

    def test_state_roundtrip_and_atomicity(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "state.json")
            self.assertTrue(save_json_state(path, {"last_run": "2026-01-01T00:00:00Z"}))
            self.assertEqual(load_json_state(path)["last_run"], "2026-01-01T00:00:00Z")
            # no stray temp file left behind
            self.assertEqual(os.listdir(tmp), ["state.json"])

    def test_load_json_state_corrupt_returns_empty(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "state.json")
            with open(path, "w") as f:
                f.write("{truncated")
            self.assertEqual(load_json_state(path), {})

    def test_checkpoint_path_never_collides(self):
        self.assertNotEqual(checkpoint_path_for(".state"), ".state")
        self.assertNotEqual(checkpoint_path_for(".state.json"), ".state.json")

    def test_atomic_write_replaces_existing(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "f.json")
            atomic_write_json(path, {"v": 1})
            atomic_write_json(path, {"v": 2})
            self.assertEqual(load_json_state(path), {"v": 2})

    def test_append_audit_entry_appends_jsonl(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "audit.jsonl")
            append_audit_entry(path, {"action": "updated", "person_id": "p1"})
            append_audit_entry(path, {"action": "dry_run", "person_id": "p2"})
            with open(path) as f:
                lines = [json.loads(line) for line in f]
            self.assertEqual(len(lines), 2)
            self.assertEqual(lines[0]["action"], "updated")
            self.assertIn("ts", lines[0])

    def test_append_audit_entry_disabled(self):
        append_audit_entry(None, {"action": "noop"})  # must not raise

    def test_load_env_file_does_not_override(self):
        with tempfile.TemporaryDirectory() as tmp:
            env_path = os.path.join(tmp, ".env")
            with open(env_path, "w") as f:
                f.write('PY_ATTIO_TEST_VAR="from_file"\n')
            os.environ["PY_ATTIO_TEST_VAR"] = "from_shell"
            try:
                load_env_file(env_path)
                self.assertEqual(os.environ["PY_ATTIO_TEST_VAR"], "from_shell")
            finally:
                del os.environ["PY_ATTIO_TEST_VAR"]


class TestSyncPersonLocations(unittest.TestCase):
    def _client_with_person(self, existing_ids):
        client = MagicMock()
        client.get_record.return_value = {
            "data": {
                "values": {
                    "name": [{"first_name": "Ada", "last_name": "Lovelace"}],
                    "locations": [{"target_record_id": i} for i in existing_ids],
                }
            }
        }
        return client

    def test_superset_skips_update(self):
        client = self._client_with_person(["l1", "l2"])
        result = sync_person_locations(
            client,
            "people",
            "locations",
            "locations",
            "p1",
            "c1",
            "Acme",
            ["l1"],
            dry_run=False,
            audit_file=None,
        )
        self.assertFalse(result)
        client.update_record.assert_not_called()

    def test_dry_run_makes_no_update_but_audits(self):
        client = self._client_with_person(["l1"])
        with tempfile.TemporaryDirectory() as tmp:
            audit = os.path.join(tmp, "audit.jsonl")
            result = sync_person_locations(
                client,
                "people",
                "locations",
                "locations",
                "p1",
                "c1",
                "Acme",
                ["l1", "l2"],
                dry_run=True,
                audit_file=audit,
            )
            self.assertTrue(result)
            client.update_record.assert_not_called()
            with open(audit) as f:
                entry = json.loads(f.readline())
            self.assertEqual(entry["action"], "dry_run")
            self.assertEqual(entry["added_location_ids"], ["l2"])

    def test_update_unions_and_audits(self):
        client = self._client_with_person(["l1"])
        with tempfile.TemporaryDirectory() as tmp:
            audit = os.path.join(tmp, "audit.jsonl")
            result = sync_person_locations(
                client,
                "people",
                "locations",
                "locations",
                "p1",
                "c1",
                "Acme",
                ["l2"],
                dry_run=False,
                audit_file=audit,
            )
            self.assertTrue(result)
            payload = client.update_record.call_args.args[2]
            sent_ids = {
                item["target_record_id"]
                for item in payload["data"]["values"]["locations"]
            }
            self.assertEqual(sent_ids, {"l1", "l2"})
            with open(audit) as f:
                entry = json.loads(f.readline())
            self.assertEqual(entry["action"], "updated")
            self.assertEqual(entry["person_name"], "Ada Lovelace")

    def test_fetch_failure_returns_none_and_audits(self):
        client = MagicMock()
        client.get_record.side_effect = RuntimeError("boom")
        with tempfile.TemporaryDirectory() as tmp:
            audit = os.path.join(tmp, "audit.jsonl")
            result = sync_person_locations(
                client,
                "people",
                "locations",
                "locations",
                "p1",
                "c1",
                "Acme",
                ["l1"],
                dry_run=False,
                audit_file=audit,
            )
            self.assertIsNone(result)
            with open(audit) as f:
                entry = json.loads(f.readline())
            self.assertEqual(entry["action"], "fetch_failed")

    def test_update_failure_returns_none(self):
        client = self._client_with_person([])
        client.update_record.side_effect = RuntimeError("boom")
        result = sync_person_locations(
            client,
            "people",
            "locations",
            "locations",
            "p1",
            "c1",
            "Acme",
            ["l1"],
            dry_run=False,
            audit_file=None,
        )
        self.assertIsNone(result)


if __name__ == "__main__":
    unittest.main()
